461:   private void mockTokenRequest(final boolean withAssertion) {
462:     final String assertionRegex = ".*client_assertion\\=[\\._\\-A-Za-z0-9]{400,500}.*";
463:     final String assertionTypeRegex = ".*client_assertion_type.*";
464:     final String clientSecret = ".*client_secret.*";
465:     final HashMap<String, String> map = new HashMap<>();
466:     map.put("access_token", ACCESS_TOKEN);
467:     map.put("token_type", TOKEN_TYPE);
468:     map.put("expires_in", "3600");
469: 
470:     try {
471:       currentWiremockRuntimeInfo
472:           .getWireMock()
473:           .register(
474:               WireMock.post(WireMock.urlPathEqualTo("/oauth/token"))
475:                   .withHeader("Content-Type", equalTo("application/x-www-form-urlencoded"))
476:                   .withHeader("Accept", equalTo("application/json"))
477:                   .withHeader("User-Agent", matching("camunda-client-java/\\d+\\.\\d+\\.\\d+.*"))
478:                   .withRequestBody(
479:                       withAssertion ? matching(assertionRegex) : notMatching(assertionRegex))
480:                   .withRequestBody(
481:                       withAssertion
482:                           ? matching(assertionTypeRegex)
483:                           : notMatching(assertionTypeRegex))
484:                   .withRequestBody(
485:                       !withAssertion ? matching(clientSecret) : notMatching(clientSecret))
486:                   .willReturn(
487:                       WireMock.aResponse()
488:                           .withBody(jsonMapper.writeValueAsString(map))
489:                           .withHeader("Content-Type", "application/json")
490:                           .withStatus(200)));
491:     } catch (final JsonProcessingException e) {
492:       throw new RuntimeException(e);
493:     }
494:   }
