681: 
682:     // then
683:     final UserTaskRecordValue createdUserTask =
684:         RecordingExporter.userTaskRecords(UserTaskIntent.CREATED)
685:             .withProcessInstanceKey(processInstanceKey)
686:             .getFirst()
687:             .getValue();
688: 
689:     assertThat(
690:             RecordingExporter.userTaskRecords()
691:                 .withProcessInstanceKey(processInstanceKey)
692:                 .limit(r -> r.getIntent() == UserTaskIntent.ASSIGNED))
693:         .extracting(Record::getValueType, Record::getIntent)
694:         .containsSubsequence(
695:             tuple(ValueType.USER_TASK, UserTaskIntent.ASSIGNING),
696:             tuple(ValueType.USER_TASK, UserTaskIntent.ASSIGNED));
697: 
698:     Assertions.assertThat(
699:             RecordingExporter.userTaskRecords(UserTaskIntent.ASSIGNED)
700:                 .withProcessInstanceKey(processInstanceKey)
701:                 .getFirst()
702:                 .getValue())
703:         .hasAssignee("foo");
704: 
705:     Assertions.assertThat(userTaskState.getUserTask(createdUserTask.getUserTaskKey()))
706:         .hasAssignee("foo");
707:   }
