71:   public UserTaskProcessor(
72:       final ProcessingState state,
73:       final MutableUserTaskState userTaskState,
74:       final KeyGenerator keyGenerator,
75:       final BpmnBehaviors bpmnBehaviors,
76:       final Writers writers,
77:       final AuthorizationCheckBehavior authCheckBehavior) {
78:     commandProcessors =
79:         new UserTaskCommandProcessors(
80:             state, keyGenerator, bpmnBehaviors, writers, authCheckBehavior);
81:     processState = state.getProcessState();
82:     this.userTaskState = userTaskState;
83:     elementInstanceState = state.getElementInstanceState();
84:     variableState = state.getVariableState();
85: 
86:     jobBehavior = bpmnBehaviors.jobBehavior();
87: 
88:     rejectionWriter = writers.rejection();
89:     responseWriter = writers.response();
90:     stateWriter = writers.state();
91:   }
