8: package io.camunda.zeebe.engine.processing.usertask.processors;
9: 
10: import io.camunda.zeebe.engine.processing.Rejection;
11: import io.camunda.zeebe.engine.processing.common.EventHandle;
12: import io.camunda.zeebe.engine.processing.identity.AuthorizationCheckBehavior;
13: import io.camunda.zeebe.engine.processing.streamprocessor.writers.StateWriter;
14: import io.camunda.zeebe.engine.processing.streamprocessor.writers.TypedCommandWriter;
15: import io.camunda.zeebe.engine.processing.streamprocessor.writers.TypedResponseWriter;
16: import io.camunda.zeebe.engine.processing.streamprocessor.writers.Writers;
17: import io.camunda.zeebe.engine.state.immutable.ElementInstanceState;
18: import io.camunda.zeebe.engine.state.immutable.ProcessingState;
19: import io.camunda.zeebe.engine.state.immutable.UserTaskState;
20: import io.camunda.zeebe.engine.state.immutable.UserTaskState.LifecycleState;
21: import io.camunda.zeebe.engine.state.instance.ElementInstance;
22: import io.camunda.zeebe.protocol.impl.record.value.usertask.UserTaskRecord;
23: import io.camunda.zeebe.protocol.record.ValueType;
24: import io.camunda.zeebe.protocol.record.intent.ProcessInstanceIntent;
25: import io.camunda.zeebe.protocol.record.intent.UserTaskIntent;
26: import io.camunda.zeebe.stream.api.records.TypedRecord;
27: import io.camunda.zeebe.util.Either;
28: import java.util.List;
29: 
30: public final class UserTaskCompleteProcessor implements UserTaskCommandProcessor {
31: 
32:   private static final String DEFAULT_ACTION = "complete";
33: 
34:   private final ElementInstanceState elementInstanceState;
35:   private final UserTaskState asyncRequestState;
36:   private final EventHandle eventHandle;
37:   private final StateWriter stateWriter;
38:   private final TypedCommandWriter commandWriter;
39:   private final TypedResponseWriter responseWriter;
40:   private final UserTaskCommandPreconditionChecker preconditionChecker;
41: 
42:   public UserTaskCompleteProcessor(
43:       final ProcessingState state,
44:       final EventHandle eventHandle,
45:       final Writers writers,
46:       final AuthorizationCheckBehavior authCheckBehavior) {
47:     elementInstanceState = state.getElementInstanceState();
48:     asyncRequestState = state.getUserTaskState();
49:     this.eventHandle = eventHandle;
50:     stateWriter = writers.state();
51:     commandWriter = writers.command();
52:     responseWriter = writers.response();
53:     preconditionChecker =
54:         new UserTaskCommandPreconditionChecker(
55:             List.of(LifecycleState.CREATED),
56:             "complete",
57:             state.getUserTaskState(),
58:             authCheckBehavior);
59:   }
60: 
61:   @Override
62:   public Either<Rejection, UserTaskRecord> validateCommand(
63:       final TypedRecord<UserTaskRecord> command) {
64:     return preconditionChecker.check(command);
65:   }
66: 
67:   @Override
68:   public void onCommand(
69:       final TypedRecord<UserTaskRecord> command, final UserTaskRecord userTaskRecord) {
70:     final long userTaskKey = command.getKey();
71: 
72:     userTaskRecord.setVariables(command.getValue().getVariablesBuffer());
73:     userTaskRecord.setAction(command.getValue().getActionOrDefault(DEFAULT_ACTION));
74: 
75:     stateWriter.appendFollowUpEvent(userTaskKey, UserTaskIntent.COMPLETING, userTaskRecord);
76:   }
77: 
78:   @Override
79:   public void onFinalizeCommand(
80:       final TypedRecord<UserTaskRecord> command, final UserTaskRecord userTaskRecord) {
81:     final long userTaskKey = command.getKey();
82: 
83:     if (command.hasRequestMetadata()) {
84:       stateWriter.appendFollowUpEvent(userTaskKey, UserTaskIntent.COMPLETED, userTaskRecord);
85:       completeElementInstance(userTaskRecord);
86: 
87:       responseWriter.writeEventOnCommand(
88:           userTaskKey, UserTaskIntent.COMPLETED, userTaskRecord, command);
89:     } else {
90:       /*
91:        * If the request metadata is not present in the received command, it indicates that
92:        * "complete" task listeners were configured, and that the normal flow of the "COMPLETE"
93:        * command was interrupted by the "COMPLETE_TASK_LISTENER" command.
94:        * In this case, we need to use the `requestId` and `requestStreamId` from the persisted
95:        * metadata, which refers to the original "COMPLETE" command, to correctly write the
96:        * response back.
97:        *
98:        * Note: It's important to retrieve this metadata from the user task state before appending
99:        * the "COMPLETED" event, as it will be cleared by the "COMPLETED" event applier.
100:        */
101:       final var recordRequestMetadata = asyncRequestState.findRecordRequestMetadata(userTaskKey);
102:       stateWriter.appendFollowUpEvent(userTaskKey, UserTaskIntent.COMPLETED, userTaskRecord);
103:       completeElementInstance(userTaskRecord);
104: 
105:       recordRequestMetadata.ifPresent(
106:           metadata ->
107:               responseWriter.writeResponse(
108:                   userTaskKey,
109:                   UserTaskIntent.COMPLETED,
110:                   userTaskRecord,
111:                   ValueType.USER_TASK,
112:                   metadata.getRequestId(),
113:                   metadata.getRequestStreamId()));
114:     }
115:   }
116: 
117:   private void completeElementInstance(final UserTaskRecord userTaskRecord) {
118:     final var userTaskElementInstanceKey = userTaskRecord.getElementInstanceKey();
119: 
120:     final ElementInstance userTaskElementInstance =
121:         elementInstanceState.getInstance(userTaskElementInstanceKey);
122: 
123:     if (userTaskElementInstance != null) {
124:       final long scopeKey = userTaskElementInstance.getValue().getFlowScopeKey();
125:       final ElementInstance scopeInstance = elementInstanceState.getInstance(scopeKey);
126: 
127:       if (scopeInstance != null && scopeInstance.isActive()) {
128:         eventHandle.triggeringProcessEvent(userTaskRecord);
129:         commandWriter.appendFollowUpCommand(
130:             userTaskElementInstanceKey,
131:             ProcessInstanceIntent.COMPLETE_ELEMENT,
132:             userTaskElementInstance.getValue());
133:       }
134:     }
135:   }
136: }
