209:       return;
210:     }
211: 
212:     final long key = keyGenerator.nextKey();
213: 
214:     writers.state().appendFollowUpEvent(key, VariableDocumentIntent.UPDATED, value);
215:     writers.response().writeEventOnCommand(key, VariableDocumentIntent.UPDATED, value, record);
216:   }
